lock;width:100%;height:auto;aspect-ratio:1/1;object-fit:cover}.ccdl .mod span{display:block;padding:14px 18px 18px}.ccdl .mod b{display:block;font-size:16px}.ccdl .mod em{display:block;font-style:normal;font-size:13px;color:var(--c-blue2);font-weight:700;margin-top:4px}html.ccp-dark-theme .ccdl .mod em{color:#7db4ff}.ccdl .faq details{background:var(--c-card);border:1px solid var(--c-line);border-radius:14px;margin-bottom:10px;padding:0 20px}.ccdl .faq summary{cursor:pointer;list-style:none;padding:17px 0;font-weight:800;font-size:16px;color:var(--c-text);display:flex;justify-content:space-between;gap:12px}.ccdl .faq summary::-webkit-details-marker{display:none}.ccdl .faq summary:after{content:&quot;+&quot;;font-size:22px;line-height:1;color:var(--c-blue2)}.ccdl .faq details[open] summary:after{content:&quot;–&quot;}.ccdl .faq p{padding:0 0 18px;color:var(--c-muted);font-size:15px}.ccdl .faq code{font-size:13px}.ccdl .cta{display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap;border-radius:24px;padding:clamp(24px,4vw,44px);color:#fff;background:linear-gradient(135deg,#06152b,#0b3f86)}.ccdl .cta h3{color:#fff;font-size:clamp(24px,3vw,34px);font-weight:850;letter-spacing:-.02em}.ccdl .cta p{color:#bfd3ee;margin-top:8px}@media(max-width:991px){.ccdl .hl{grid-template-columns:1fr}.ccdl .mock{max-width:520px}.ccdl .stats,.ccdl .req{grid-template-columns:repeat(2,1fr)}.ccdl .g3,.ccdl .mods{grid-template-columns:repeat(2,1fr)}.ccdl .dl{grid-template-columns:1fr}}@media(max-width:575px){.ccdl .mock{transform:none;border-width:5px}.ccdl .kp b{font-size:16px}.ccdl .g3,.ccdl .g2,.ccdl .mods{grid-template-columns:1fr}.ccdl .stats{margin-top:-24px;padding:0 8px}.ccdl .btn{width:100%}.ccdl section{margin-bottom:40px}.ccdl .req{grid-template-columns:1fr 1fr}}&lt;/style&gt;&lt;div class=&quot;ccdl&quot; lang=&quot;uk&quot;&gt;&lt;div class=&quot;w&quot;&gt;&lt;section class=&quot;hero&quot;&gt;&lt;div class=&quot;hl&quot;&gt;&lt;div&gt;&lt;div class=&