HA-256 file&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;warn&quot;&gt;⚠ Before installing or upgrading an existing store, make a full backup of your files and database and test the upgrade on a staging copy first.&lt;/div&gt;&lt;/section&gt;&lt;section&gt;&lt;div class=&quot;hd&quot;&gt;&lt;span class=&quot;k&quot;&gt;Features&lt;/span&gt;&lt;h3&gt;What is inside CodeCart PRO&lt;/h3&gt;&lt;p&gt;The familiar OpenCart on a modernized foundation — for store owners, developers and integrators.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;g3&quot;&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;ic&quot;&gt;&lt;svg viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;#fff&quot; stroke-width=&quot;1.7&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M12 3l8 4.5v9L12 21l-8-4.5v-9z&quot;/&gt;&lt;path d=&quot;M4 7.5l8 4.5 8-4.5M12 12v9&quot;/&gt;&lt;/svg&gt;&lt;/div&gt;&lt;h4&gt;Catalog and sales&lt;/h4&gt;&lt;p&gt;Products, categories, attributes, customers, orders, cart, shipping and payments.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;ic&quot;&gt;&lt;svg viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;#fff&quot; stroke-width=&quot;1.7&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M4 17a8.5 8.5 0 1 1 16 0&quot;/&gt;&lt;path d=&quot;M12 17l4-6&quot;/&gt;&lt;circle cx=&quot;12&quot; cy=&quot;17&quot; r=&quot;1.2&quot;/&gt;&lt;/svg&gt;&lt;/div&gt;&lt;h4&gt;Modernized core&lt;/h4&gt;&lt;p&gt;Updated libraries, MySQL/MariaDB, PHP 8.x, caching and data handling.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;ic&quot;&gt;&lt;svg viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;#fff&quot; stroke-width=&quot;1.7&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M9 3v5M15 3v5&quot;/&gt;&lt;path d=&quot;M6 8h12v3a6 6 0 0 1-12 0z&quot;/&gt;&lt;path d=&quot;M12 17v4&quot;/&gt;&lt;/svg&gt;&lt;/div&gt;&lt;h4&gt;Flexible architecture&lt;/h4&gt;&lt;p&gt;MVC-L, OCMOD and Events, modern PHP services and PSR-4.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;ic&quot;&gt;&lt;svg viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;#fff&quot; stroke-width=&quot;1.7&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M12 3l7.5 3v5.5c0 4.5-3 8-7.5 9.5-4.5-1.5-7.5-5-7.5-9.5V6z&quot;/&gt;&lt;path d=&quot;M8.7 12l2.3 2.3 4.3-4.6&quot;/&gt;&lt;/svg&gt;&lt;/div&gt;&lt;h4&gt;Security&lt;/h4&gt;&lt;p&gt;Improved authentication, sessions, form protection, diagnostics and audit logging.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;ic&quot;&gt;&lt;svg viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;#fff&quot; stroke-width=&quot;1.7&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;circle cx=&quot;10.5&quot; cy=&quot;10.5&quot; r=&quot;6.5&quot;/&gt;&lt;path d=&quot;m15.5 15.5 5 5&quot;/&gt;&lt;path d=&quot;M7.5 12.5l2-2.5 2 1.5 2.2-3&quot;/&gt;&lt;/svg&gt;&lt;/div&gt;&lt;h4&gt;SEO and multilingual&lt;/h4&gt;&lt;p&gt;SEO URLs, canonical, sitemap and multilingual content for search optimization.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;ic&quot;&gt;&lt;svg viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;#fff&quot; stroke-width=&quot;1.7&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;rect x=&quot;3&quot; y=&quot;4&quot; width=&quot;18&quot; height=&quot;16&quot; rx=&quot;3&quot;/&gt;&lt;path d=&quot;M3 9h18M9 9v11&quot;/&gt;&lt;/svg&gt;&lt;/div&gt;&lt;h4&gt;Themes and extensions&lt;/h4&gt;&lt;p&gt;Familiar OpenCart 3.x extension mechanisms. Third-party modules must be checked for compatibility.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/section&gt;&lt;section&gt;&lt;div class=&quot;hd&quot;&gt;&lt;span class=&quot;k&quot;&gt;Quick start&lt;/span&gt;&lt;h3&gt;Install in three steps&lt;/h3&gt;&lt;p&gt;For a new installation, use the official package with bundled dependencies.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;g3&quot;&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;num&quot;&gt;1&lt;/div&gt;&lt;h4&gt;Download the package&lt;/h4&gt;&lt;p&gt;Get the ZIP from GitHub Releases and unpack it on your computer.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;num&quot;&gt;2&lt;/div&gt;&lt;h4&gt;Upload to hosting&lt;/h4&gt;&lt;p&gt;Copy the contents of the upload folder to the site root and create an empty database.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;card&quot;&gt;&lt;div class=&quot;num&quot;&gt;3&lt;/div&gt;&lt;h4&gt;Run the installer&lt;/h4&gt;&lt;p&gt;Open /install/ in your browser, pass the requirements check and finish the setup.&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;lk&quot;&gt;&lt;a href=&quot;https://github.com/CodeCartPro/CodeCartPro-3.0.6.0/blob/main/documentation/INSTALL.md&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Installation guide&lt;/a&gt;&lt;a href=&quot;https://github.com/CodeCartPro/CodeCartPro-3.0.6.0/blob/main/documentation/UPGRADE.md&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Upgrading a store&lt;/a&gt;&lt;a href=&quot;https://github.com/CodeCartPro/CodeCartPro-3.0.6.0/blob/main/documentation/COMPATIBILITY.md&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Compatibility&lt;/a&gt;&lt;/div&gt;&lt;/section&gt;&lt;section&gt;&lt;div class=&quot;hd&quot;&gt;&lt;span class=&quot;k&quot;&gt;Requirements&lt;/span&gt;&lt;h3&gt;Prepare your server&lt;/h3&gt;&lt;/div&gt;&lt;div class=&quot;req&quot;&gt;&lt;div&gt;&lt;small&gt;PHP&lt;/small&gt;&lt;b&gt;8.1–8.5&lt;/b&gt;&lt;/div&gt;&lt;div&gt;&lt;small&gt;Database&lt;/small&gt;&lt;b&gt;MySQL / MariaDB&lt;/b&gt;&lt;/div&gt;&lt;div&gt;&lt;small&gt;Web server&lt;/small&gt;&lt;b&gt;Apache / nginx&lt;/b&gt;&lt;/div&gt;&lt;div&gt;&lt;small&gt;Protocol&lt;/small&gt;&lt;b&gt;HTTPS&lt;/b&gt;&lt;/div&gt;&lt;/div&gt;&lt;p class=&quot;note&quot;&gt;PHP 8.1–8.3 is best for maximum compatibility with existing OpenCart extensions. The core also supports PHP 8.4–8.5, but third-party module compatibility is not guaranteed.&lt;/p&gt;&lt;/section&gt;&lt;section&gt;&lt;div class=&quot;hd&quot;&gt;&lt;span class=&quot;k&quot;&gt;Modules&lt;/span&gt;&lt;h3&gt;Extend the system with CodeCart PRO modules&lt;/h3&gt;&lt;p&gt;SEO, AI, import and export, shipping, payments, security. Try modules in the demo admin before you buy.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;mods&quot;&gt;&lt;a class=&quot;mod&quot; href=&quot;/index.php?route=product/product&amp;amp;product_id=127&quot;&gt;&lt;img src=&quot;/image/catalog/codecartpro/products/ai-content-pro.webp&quot; alt=&quot;AI Content PRO&quot; loading=&quot;lazy&quot; width=&quot;450&quot; height=&quot;450&quot;&gt;&lt;span&gt;&lt;b&gt;AI Content PRO&lt;/b&gt;&lt;em&gt;Learn more →&lt;/em&gt;&lt;/span&gt;&lt;/a&gt;&lt;a class=&quot;mod&quot; href=&quot;/index.php?route=product/product&amp;amp;product_id=63&quot;&gt;&lt;img src=&quot;/image/catalog/codecartpro/products/ai-store-assistant-pro.webp&quot; alt=&quot;AI Store Assistant PRO is a smart seller-consultant for OpenCart and ocStore&quot; loading=&quot;lazy&quot; width=&quot;450&quot; height=&quot;450&quot;&gt;&lt;span&gt;&lt;b&gt;AI Store Assistant PRO is a smart seller-consultant for OpenCart and ocStore&lt;/b&gt;&lt;em&gt;Learn more →&lt;/em&gt;&lt;/span&gt;&lt;/a&gt;&lt;a class=&quot;mod&quot; href=&quot;/index.php?route=product/product&amp;amp;product_id=80&quot;&gt;&lt;img src=&quot;/image/catalog/codecartpro/products/seo-url-pro.webp&quot; alt=&quot;SEO URL Pro&quot; loading=&quot;lazy&quot; width=&quot;450&quot; height=&quot;450&quot;&gt;&lt;span&gt;&lt;b&gt;SEO URL Pro&lt;/b&gt;&lt;em&gt;Learn more →&lt;/em&gt;&lt;/span&gt;&lt;/a&gt;&lt;a class=&quot;mod&quot; href=&quot;/index.php?route=product/product&amp;amp;product_id=66&quot;&gt;&lt;img src=&quot;/image/catalog/codecartpro/products/avif-webp-image-pro.webp&quot; alt=&quot;AVIF WebP Image Pro&quot; loading=&quot;lazy&quot; width=&quot;450&quot; height=&quot;450&quot;&gt;&lt;span&gt;&lt;b&gt;AVIF WebP Image Pro&lt;/b&gt;&lt;em&gt;Learn more →&lt;/em&gt;&lt;/span&gt;&lt;/a&gt;&lt;a class=&quot;mod&quot; href=&quot;/index.php?route=product/product&amp;amp;product_id=72&quot;&gt;&lt;img src=&quot;/image/catalog/codecartpro/products/nova-poshta-pro.webp&quot; alt=&quot;Nova Poshta Pro&quot; loading=&quot;lazy&quot; width=&quot;450&quot; height=&quot;450&quot;&gt;&lt;span&gt;&lt;b&gt;Nova Poshta Pro&lt;/b&gt;&lt;em&gt;Learn more →&lt;/em&gt;&lt;/span&gt;&lt;/a&gt;&lt;a class=&quot;mod&quot; href=&quot;/index.php?route=product/product&amp;amp;product_id=73&quot;&gt;&lt;img src=&quot;/image/catalog/codecartpro/products/import-export-pro.webp&quot; alt=&quot;Import Export Pro&quot; loading=&quot;lazy&quot; width=&quot;450&quot; height=&quot;450&quot;&gt;&lt;span&gt;&lt;b&gt;Import Export Pro&lt;/b&gt;&lt;em&gt;Learn more →&lt;/em&gt;&lt;/span&gt;&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;lk&quot; style=&quot;margin-top:22px&quot;&gt;&lt;a class=&quot;btn btn-b&quot; style=&quot;color:#fff&quot; href=&quot;/codecartpro-en/&quot;&gt;Browse all modules →&lt;/a&gt;&lt;a href=&quot;/buy-modules-en/&quot;&gt;How to buy modules&lt;/a&gt;&lt;/div&gt;&lt;/section&gt;&lt;section class=&quot;faq&quot;&gt;&lt;div class=&quot;hd&quot;&gt;&lt;span class=&quot;k&quot;&gt;Q&amp;amp;A&lt;/span&gt;&lt;h3&gt;Frequently asked questions&lt;/h3&gt;&lt;/div&gt;&lt;details&gt;&lt;summary&gt;Is CodeCart PRO really free?&lt;/summary&gt;&lt;p&gt;Yes. The core is distributed free under GNU GPL v3 and can be used in commercial stores. Some additional modules and services may be paid.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Do I need to register or pay to download?&lt;/summary&gt;&lt;p&gt;No. The archive downloads directly from GitHub without registration, cart or payment.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;How do I verify the archive?&lt;/summary&gt;&lt;p&gt;Compare the file’s SHA-256 with the checksum on this page. Linux/macOS: &lt;code&gt;sha256sum CodeCart-3.0.6.zip&lt;/code&gt;. Windows: &lt;code&gt;certutil -hashfile CodeCart-3.0.6.zip SHA256&lt;/code&gt;.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Can I use OpenCart and ocStore modules?&lt;/summary&gt;&lt;p&gt;CodeCart keeps compatible OpenCart/ocStore 3.x mechanisms, including MVC-L, OCMOD and Events. Each third-party module still depends on its own code, the PHP version and your theme.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Can I upgrade an existing store?&lt;/summary&gt;&lt;p&gt;Yes, an upgrade path is provided. Back up your files and database first, then test themes, modules, payments, shipping and checkout on a staging copy.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Is PHP 8.5 supported?&lt;/summary&gt;&lt;p&gt;The core is built for PHP 8.1–8.5. Existing extensions usually run best on PHP 8.1–8.3; test third-party themes and modules separately.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Where can I see it in action?&lt;/summary&gt;&lt;p&gt;Open the demo store &lt;a href=&quot;https://test.codecartpro.com/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;test.codecartpro.com&lt;/a&gt; and its demo admin.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Can I modify the source code?&lt;/summary&gt;&lt;p&gt;Yes. GNU GPL v3 allows you to study, modify and distribute the software under its terms.&lt;/p&gt;&lt;/details&gt;&lt;/section&gt;&lt;section class=&quot;cta&quot;&gt;&lt;div&gt;&lt;h3&gt;Start with CodeCart PRO&lt;/h3&gt;&lt;p&gt;Download the free system, explore its features and launch your own store.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;btn btn-y&quot; href=&quot;https://github.com/CodeCartPro/CodeCartPro-3.0.6.0/releases/download/v3.0.6.0/CodeCart-3.0.6.zip&quot; rel=&quot;noopener&quot;&gt;Download CodeCart 3.0.6 ↓&lt;/a&gt;&lt;/section&gt;&lt;div class=&quot;lk&quot; style=&quot;justify-content:center&quot;&gt;&lt;a href=&quot;https://test.codecartpro.com/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Store demo&lt;/a&gt;&lt;a href=&quot;https://test.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Admin demo&lt;/a&gt;&lt;a href=&quot;https://github.com/CodeCartPro/CodeCartPro-3.0.6.0&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;GitHub&lt;/a&gt;&lt;a href=&quot;https://t.me/+tUZNEgY3aUk4MGIy&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Community&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;script type=&quot;application/ld+json&quot;&gt;{&quot;@context&quot;: &quot;https://schema.org&quot;, &quot;@type&quot;: &quot;SoftwareApplication&quot;, &quot;name&quot;: &quot;CodeCart PRO&quot;, &quot;softwareVersion&quot;: &quot;3.0.6.0&quot;, &quot;applicationCategory&quot;: &quot;BusinessApplication&quot;, &quot;operatingSystem&quot;: &quot;Linux, Windows (PHP 8.1–8.5)&quot;, &quot;license&quot;: &quot;https://www.gnu.org/licenses/gpl-3.0.html&quot;, &quot;downloadUrl&quot;: &quot;https://github.com/CodeCartPro/CodeCartPro-3.0.6.0/releases/download/v3.0.6.0/CodeCart-3.0.6.zip&quot;, &quot;fileSize&quot;: &quot;15.2 MB&quot;, &quot;offers&quot;: {&quot;@type&quot;: &quot;Offer&quot;, &quot;price&quot;: &quot;0&quot;, &quot;priceCurrency&quot;: &quot;USD&quot;}, &quot;description&quot;: &quot;Download the free CodeCart PRO 3.0.6.0 system based on OpenCart and ocStore 3.x: GNU GPL v3, PHP 8.1–8.5, direct ZIP download without registration. CodeCart PRO modules are in the catalog.&quot;}&lt;/script&gt;', `meta_title`='Download CodeCart PRO 3.0.6.0 — free system for OpenCart and ocStore', `meta_description`='Download the free CodeCart PRO 3.0.6.0 system based on OpenCart and ocStore 3.x: GNU GPL v3, PHP 8.1–8.5, direct ZIP download without registration. CodeCart PRO modules are in the catalog.', `meta_keyword`='download codecart pro, codecart 3.0.6, free opencart cms, ocstore 3', `meta_h1`='Download CodeCart PRO' WHERE `information_id`=14 AND `language_id`=2;
UPDATE `oc_information_description` SET `title`='Скачать CodeCart PRO', `description`='&lt;style&gt;.ccdl{--c-bg:#fff;--c-soft:#f3f7fd;--c-card:#fff;--c-text:#13294a;--c-muted:#5b6f8a;--c-line:#dfe8f4;--c-blue:#0057b7;--c-blue2:#1769e0;--c-yellow:#ffd700;--c-navy:#06152b;font-family:inherit;color:var(--c-text);line-height:1.6}html.ccp-dark-theme .ccdl{--c-bg:#0f172a;--c-soft:#111c33;--c-card:#1e293b;--c-text:#f1f5fb;--c-muted:#b8c6da;--c-line:#334155}.ccdl *{box-sizing:border-box}.ccdl h2,.ccdl h3,.ccdl h4,.ccdl p{margin:0}.ccdl a{text-decoration:none}.ccdl section{margin:0 0 56px}.ccdl .w{max-width:1200px;margin:0 auto}.ccdl .k{display:inline-block;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--c-blue2);margin-bottom:10px}html.ccp-dark-theme .ccdl .k{color:#7db4ff}.ccdl .hd{margin-bottom:28px;max-width:760px}.ccdl .hd h3{font-size:clamp(26px,3vw,36px);line-height:1.15;font-weight:850;letter-spacing:-.025em;color:var(--c-text)}.ccdl .hd p{margin-top:12px;color:var(--c-muted);font-size:16px}.ccdl .btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:14px 26px;border-radius:14px;font-weight:800;font-size:16px;transition:.2s;text-align:center}.ccdl .btn-y{background:var(--c-yellow);color:#071a33!important;box-shadow:0 12px 28px rgba(255,215,0,.28)}.ccdl .btn-y:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(255,215,0,.4)}.ccdl .btn-o{border:1.5px solid rgba(255,255,255,.35);color:#fff!important;background:rgba(255,255,255,.08)}.ccdl .btn-o:hover{background:rgba(255,255,255,.16)}.ccdl .btn-b{background:var(--c-blue);color:#fff!important}.ccdl .btn-b:hover{background:var(--c-blue2)}/* hero */.ccdl .hero{position:relative;overflow:hidden;border-radius:26px;padding:clamp(28px,5vw,64px);color:#fff;background:radial-gradient(circle at 85% 15%,rgba(255,215,0,.22),transparent 40%),radial-gradient(circle at 0 100%,rgba(23,105,224,.6),transparent 50%),linear-gradient(135deg,#06152b,#0a2a55 60%,#0b3f86)}.ccdl .hero:before{content:&quot;&quot;;position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:44px 44px;-webkit-mask-image:radial-gradient(circle at 75% 25%,#000,transparent 70%);mask-image:radial-gradient(circle at 75% 25%,#000,transparent 70%)}.ccdl .hl{position:relative;display:grid;grid-template-columns:1.1fr .9fr;gap:44px;align-items:center}.ccdl .pill{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:#cfe0f6;margin-bottom:22px}.ccdl .pill:before{content:&quot;&quot;;width:9px;height:9px;border-radius:50%;background:var(--c-yellow);box-shadow:0 0 0 6px rgba(255,215,0,.18)}.ccdl .hero h2{font-size:clamp(34px,4.6vw,58px);line-height:1.06;font-weight:900;letter-spacing:-.035em;color:#fff;margin-bottom:20px}.ccdl .hero h2 span{color:var(--c-yellow)}.ccdl .hero .lead{font-size:18px;line-height:1.7;color:#bfd3ee;margin-bottom:28px;max-width:640px}.ccdl .acts{display:flex;flex-wrap:wrap;gap:12px}.ccdl .small{font-size:13px;color:#9fbbe0;margin-top:16px}.ccdl .tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:26px}.ccdl .tags span{font-size:12px;font-weight:600;color:#c3d6f0;border:1px solid rgba(255,255,255,.2);border-radius:8px;padding:5px 11px}.ccdl .mock{background:#f6f9ff;border:8px solid rgba(255,255,255,.14);border-radius:20px;overflow:hidden;box-shadow:0 30px 70px rgba(0,0,0,.4);transform:rotate(-2.5deg)}.ccdl .mt{background:#0c2749;color:#fff;display:flex;justify-content:space-between;padding:13px 18px;font-size:14px;font-weight:800}.ccdl .mt em{font-style:normal;color:var(--c-yellow)}.ccdl .mt small{opacity:.7}.ccdl .mb{display:flex}.ccdl .ms{width:54px;background:#eaf1fb;padding:16px 0;display:flex;flex-direction:column;gap:12px;align-items:center}.ccdl .ms i{width:22px;height:22px;border-radius:7px;background:#c5d6ee}.ccdl .ms i:first-child{background:var(--c-blue2)}.ccdl .mm{flex:1;padding:16px;display:flex;flex-direction:column;gap:12px}.ccdl .kp{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.ccdl .kp div{background:#fff;border:1px solid #dde8f6;border-radius:10px;padding:9px 11px;color:#27456b;font-size:11px}.ccdl .kp b{display:block;font-size:20px;color:#0f5fd0;white-space:nowrap}.ccdl .br{height:96px;display:flex;gap:9px;align-items:flex-end;background:#fff;border:1px solid #dde8f6;border-radius:10px;padding:11px}.ccdl .br i{flex:1;border-radius:5px 5px 0 0;background:linear-gradient(#69adff,#1670df)}/* stats */.ccdl .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:-34px;position:relative;padding:0 clamp(12px,3vw,40px)}.ccdl .stats div{background:var(--c-card);border:1px solid var(--c-line);border-radius:16px;padding:18px 20px;box-shadow:0 14px 34px rgba(8,30,66,.12)}.ccdl .stats small{display:block;font-size:12px;color:var(--c-muted);font-weight:600;letter-spacing:.04em;text-transform:uppercase}.ccdl .stats b{display:block;font-size:20px;margin-top:2px;color:var(--c-text)}/* download card */.ccdl .dl{display:grid;grid-template-columns:1fr auto;gap:24px;align-items:center;background:var(--c-card);border:1px solid var(--c-line);border-radius:22px;padding:28px 32px;box-shadow:0 18px 44px rgba(8,30,66,.08)}.ccdl .dl h4{font-size:24px;font-weight:850;color:var(--c-text);margin:6px 0}.ccdl .ft{font-size:11px;font-weight:800;letter-spacing:.12em;color:var(--c-blue2)}.ccdl .hash{margin-top:18px;padding:14px 18px;border-radius:12px;background:var(--c-soft);border:1px dashed var(--c-line);font-size:13px;color:var(--c-muted)}.ccdl .hash code{display:block;margin-top:6px;word-break:break-all;font-size:13px;color:var(--c-text);background:none;border:0;padding:0}.ccdl .lk{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.ccdl .lk a{font-size:14px;font-weight:700;color:var(--c-blue2);border:1px solid var(--c-line);background:var(--c-card);border-radius:10px;padding:9px 16px}.ccdl .lk a:hover{border-color:var(--c-blue2)}html.ccp-dark-theme .ccdl .lk a{color:#7db4ff}.ccdl .warn{margin-top:18px;padding:16px 20px;border-radius:14px;background:#fff8dc;border:1px solid #f0dd85;color:#5c4a00;font-size:14px}html.ccp-dark-theme .ccdl .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}/* features / steps / mods */.ccdl .g3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ccdl .g2{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.ccdl .card{background:var(--c-card);border:1px solid var(--c-line);border-radius:18px;padding:24px;transition:.2s}.ccdl .card:hover{transform:translateY(-3px);box-shadow:0 18px 40px rgba(8,30,66,.12)}.ccdl .ic{width:50px;height:50px;border-radius:14px;display:flex;align-items:center;justify-content:center;margin-bottom:16px;background:linear-gradient(145deg,#1769e0,#0a3f86)}.ccdl .ic svg{width:26px;height:26px}.ccdl .card h4{font-size:18px;font-weight:800;margin-bottom:8px;color:var(--c-text)}.ccdl .card p{font-size:15px;color:var(--c-muted)}.ccdl .num{width:46px;height:46px;border-radius:50%;background:var(--c-yellow);color:#071a33;font-weight:900;font-size:19px;display:flex;align-items:center;justify-content:center;margin-bottom:14px}.ccdl .req{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.ccdl .req div{background:var(--c-soft);border:1px solid var(--c-line);border-radius:14px;padding:16px 18px}.ccdl .req small{display:block;font-size:12px;color:var(--c-muted);font-weight:700;text-transform:uppercase;letter-spacing:.05em}.ccdl .req b{font-size:19px;color:var(--c-text)}.ccdl .note{font-size:13px;color:var(--c-muted);margin-top:14px}.ccdl .mods{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ccdl .mod{display:block;background:var(--c-card);border:1px solid var(--c-line);border-radius:18px;overflow:hidden;color:var(--c-text);transition:.2s}.ccdl .mod:hover{transform:translateY(-3px);box-shadow:0 18px 40px rgba(8,30,66,.14)}.ccdl .mod img{display:block;width:100%;height:auto;aspect-ratio:1/1;object-fit:cover}.ccdl .mod span{display:block;padding:14px 18px 18px}.ccdl .mod b{display:block;font-size:16px}.ccdl .mod em{display:block;font-style:normal;font-size:13px;color:var(--c-blue2);font-weight:700;margin-top:4px}html.ccp-dark-theme .ccdl .mod em{color:#7db4ff}.ccdl .faq details{background:var(--c-card);border:1px solid var(--c-line);border-radius:14px;margin-bottom:10px;padding:0 20px}.ccdl .faq summary{cursor:pointer;list-style:none;padding:17px 0;font-weight:800;font-size:16px;color:var(--c-text);display:flex;justify-content:space-between;gap:12px}.ccdl .faq summary::-webkit-details-marker{display:none}.ccdl .faq summary:after{content:&quot;+&quot;;font-size:22px;line-height:1;color:var(--c-blue2)}.ccdl .faq details[open] summary:after{content:&quot;–&quot;}.ccdl .faq p{padding:0 0 18px;color:var(--c-muted);font-size:15px}.ccdl .faq code{font-size:13px}.ccdl .cta{display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap;border-radius:24px;padding:clamp(24px,4vw,44px);color:#fff;background:linear-gradient(135deg,#06152b,#0b3f86)}.ccdl .cta h3{color:#fff;font-size:clamp(24px,3vw,34px);font-weight:850;letter-spacing:-.02em}.ccdl .cta p{color:#bfd3ee;margin-top:8px}@media(max-width:991px){.ccdl .hl{grid-template-columns:1fr}.ccdl .mock{max-width:520px}.ccdl .stats,.ccdl .req{grid-template-columns:repeat(2,1fr)}.ccdl .g3,.ccdl .mods{grid-template-columns:repeat(2,1fr)}.ccdl .dl{grid-template-columns:1fr}}@media(max-width:575px){.ccdl .mock{transform:none;border-width:5px}.ccdl .kp b{font-size:16px}.ccdl .g3,.ccdl .g2,.ccdl .mods{grid-template-columns:1fr}.ccdl .stats{margin-top:-24px;padding:0 8px}.ccdl .btn{width:100%}.ccdl section{margin-bottom:40px}.ccdl .req{grid-template-columns:1fr 1fr}}&lt;/style&gt;&lt;div class=&quot;ccdl&quot; lang=&quot;ru&quot;&gt;&lt;div class=&quot;w&quot;&gt;&lt;section class=&quot;hero&quot;&gt;&lt;div class=&quot;hl&quot;&gt;&lt;div&gt;&lt;div class=&quot